if (/^[<>]/.test(spec)) {
    const parts = spec.split(/\s+/);
    if (parts.length > 2) return null;
    let lower: Bound = null;
    let upper: Bound = null;
    for (const part of parts) {
        const m = /^(>=|>|<=|<)(.*)$/.exec(part);
        const v = m ? full(m[2]) : null;
        if (!m || !v) return null;
        if (m[1].startsWith(">")) {
            if (lower) return null;
            lower = at(v, m[1] === ">=");
        } else {
            if (upper) return null;
            upper = at(v, m[1] === "<=");
        }
    }
    return { lower, upper };
}

